#include <iostream>
#include <string>
#include <vector>
#include "searchengine/searchengine.hpp"

static std::string mode_name(SearchMode m) {
    switch (m) {
        case SearchMode::Or: return "Or";
        case SearchMode::And: return "And";
        case SearchMode::Phrase: return "Phrase";
        case SearchMode::Not: return "Not";
        case SearchMode::Near: return "Near";
    }
    return "Unknown";
}

int main() {
    SearchEngine se;

    auto bad = se.load_directory("does-not-exist");
    std::cout << "invalid_dir_ok=" << (!bad ? "true" : "false") << "\n";

    auto loaded = se.load_directory("data");
    if (!loaded) {
        std::cout << "load_data_ok=false\n";
        return 1;
    }
    std::cout << "load_data_ok=true\n";
    std::cout << "loaded_count=" << *loaded << "\n";

    std::vector<SearchRequest> reqs;
    reqs.push_back(SearchRequest{.mode=SearchMode::Or, .query="harry magic"});
    reqs.push_back(SearchRequest{.mode=SearchMode::And, .query="harry magic"});
    reqs.push_back(SearchRequest{.mode=SearchMode::Phrase, .query="harry potter"});
    reqs.push_back(SearchRequest{.mode=SearchMode::Not, .query="harry voldemort"});
    reqs.push_back(SearchRequest{.mode=SearchMode::Near, .near_left="harry", .near_right="potter", .near_distance=3});

    for (const auto& req : reqs) {
        auto resp = se.search_with_context(req);
        std::cout << mode_name(req.mode) << "_hits=" << resp.hits.size() << "\n";
        if (!resp.hits.empty()) {
            const auto& h = resp.hits.front();
            std::cout << mode_name(req.mode) << "_sample_book=" << h.book_name << "\n";
            std::cout << mode_name(req.mode) << "_sample_line=" << h.line << "\n";
            std::cout << mode_name(req.mode) << "_sample_context_cur_empty=" << (h.context.cur.empty() ? "true" : "false") << "\n";
        }
    }

    SearchRequest no_match{.mode=SearchMode::Or, .query="zzzxxyyqq impossibletoken"};
    auto no_resp = se.search_with_context(no_match);
    std::cout << "no_match_hits=" << no_resp.hits.size() << "\n";

    return 0;
}
